'use strict';
function financeToolbar(){return `<div class="finance-toolbar"><span class="finance-source"><span class="status-dot"></span>Ручной учёт</span><div><button class="btn primary" data-finance="revenue">${icon('plus')}Внести выручку</button><button class="btn secondary" data-finance="plan">${icon('chart')}Финансовый план</button><button class="text-btn" data-business="bank">Подключить счёт${icon('arrow')}</button></div></div>`}
function notifyScore(label,before){const after=M.dashboard(state,period,0).score;notify(`${label}. Индекс: ${scoreText(before)} → ${scoreText(after)}${after===before?' · финансовый риск не изменился':''}`)}
function scoreModal(){const d=M.dashboard(state,period,uplift);modal('Что влияет на индекс',`<div class="index-overview"><strong>${scoreText(d.score)}<small> / 100</small></strong><span>Финансовое состояние по текущему плану</span></div><div class="context-row"><span>Запас денег</span><strong>${scoreText(d.liquidityScore)} из 70</strong></div><div class="context-row"><span>Операционная маржа</span><strong>${scoreText(d.profitabilityScore)} из 30</strong></div><p style="margin-top:16px">Запас денег учитывает минимальный остаток (70%) и остаток в конце прогноза (30%). Он сопоставляется с расходами на три дня. Чем больше резерв, тем выше оценка. Маржа за ${period} дней даёт до 30 баллов: один балл за процентный пункт.</p><p class="small-caption">Выручка, расходы, остаток и плановые платежи влияют на расчёт сразу после сохранения. Отметка оплаты переносит сумму из будущих обязательств в текущие расходы денег и сама по себе не повышает индекс.</p><button class="btn primary full" data-action="close">Понятно</button>`)}
function indexPreview(next){const before=M.dashboard(state,period,0),after=M.dashboard(next,period,0),delta=Math.round((after.score-before.score)*10)/10;return `<span>Индекс после сохранения</span><strong>${scoreText(before.score)} <i>→</i> ${scoreText(after.score)} <small class="${delta<0?'negative':'positive'}">${delta>0?'+':''}${scoreText(delta)}</small></strong><span>Минимальный остаток: ${money(after.minBalance)}</span>`}
function revenueValues(){return {date:$('#revenue-date').value,amount:Number($('#revenue-amount').value),orders:Number($('#revenue-orders').value)}}
function revenueModal(){const h=M.adjustedHistory(state,90).find(h=>h.date===M.DATE);modal('Выручка за день',`<p>Укажите фактическую выручку после возвратов. Повторное сохранение заменит прежние данные за выбранный день.</p><form id="revenue-form"><div class="field"><label for="revenue-date">Дата</label><input id="revenue-date" type="date" value="${M.DATE}" min="${M.addDay(-89)}" max="${M.DATE}" required></div><div class="field-row"><div class="field"><label for="revenue-amount">Выручка после возвратов, ₽</label><input id="revenue-amount" type="number" min="0" max="100000000" step="1" value="${h.revenue-h.refunds}" required></div><div class="field"><label for="revenue-orders">Количество покупок</label><input id="revenue-orders" type="number" min="0" max="1000000" step="1" value="${h.orders}" required></div></div><div class="index-preview" id="finance-preview">${indexPreview(state)}</div><p class="small-caption">Остаток изменится на разницу с прежней выручкой. Фактические продажи не меняют ожидания будущих дней — они настраиваются в финансовом плане.</p><div class="field-error" id="finance-error" role="alert"></div><button class="btn primary full" type="submit">Сохранить выручку</button></form>`)}
function planValues(){return {balance:Number($('#plan-balance').value),dailyRevenue:Number($('#plan-revenue').value),dailyExpenses:Number($('#plan-expenses').value)}}
function planModal(){const c=M.planValues(state);modal('Финансовый план',`<p>Задайте текущий остаток и ожидаемые ежедневные поступления и расходы на следующие 14 дней.</p><form id="plan-form"><div class="field"><label for="plan-balance">Остаток сейчас, ₽</label><input id="plan-balance" type="number" min="-100000000" max="100000000" step="1" value="${available()}" required></div><div class="field-row"><div class="field"><label for="plan-revenue">Поступления в день, ₽</label><input id="plan-revenue" type="number" min="0" max="100000000" step="1" value="${c.dailyRevenue}" required></div><div class="field"><label for="plan-expenses">Текущие расходы в день, ₽</label><input id="plan-expenses" type="number" min="0" max="100000000" step="1" value="${c.dailyExpenses}" required></div></div><p class="small-caption">Укажите расходы без платежей из календаря: аренда, зарплата, налоги и поставки прибавляются к прогнозу отдельно.</p><div class="index-preview" id="finance-preview">${indexPreview(M.withCashPlan(state,{balance:available(),...c}))}</div><div class="field-error" id="finance-error" role="alert"></div><button class="btn primary full" type="submit">Сохранить и пересчитать</button></form>`)}
function paymentValues(){return {amount:Number($('#payment-amount').value),day:Math.round((Date.parse($('#payment-date').value+'T12:00:00Z')-Date.parse(M.DATE+'T12:00:00Z'))/86400000)}}
function withPayment(v){const next=structuredClone(state),p=next.payments.find(p=>p.id===$('#payment-id').value);p.amount=v.amount;p.day=v.day;return next}
function paymentModal(id){const p=state.payments.find(p=>p.id===id);if(!p||p.paid)return;if(id==='tax'){taxModal();return}modal('Изменить обязательство',`<p>${esc(p.name)}</p><form id="payment-form"><input id="payment-id" type="hidden" value="${esc(id)}"><div class="field-row"><div class="field"><label for="payment-amount">Сумма, ₽</label><input id="payment-amount" type="number" min="1" max="100000000" step="1" value="${p.amount}" required></div><div class="field"><label for="payment-date">Дата оплаты</label><input id="payment-date" type="date" min="${M.addDay(1)}" max="${M.addDay(90)}" value="${M.addDay(p.day)}" required></div></div><div class="index-preview" id="finance-preview">${indexPreview(state)}</div><p class="small-caption">Платёж останется в календаре. Если новая дата позже горизонта прогноза, он не попадёт в ближайшие 14 дней. Перенос срока согласуйте с получателем.</p><div class="field-error" id="finance-error" role="alert"></div><button class="btn primary full" type="submit">Сохранить обязательство</button></form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-finance="payment"]');if(b)paymentModal(b.dataset.id)});
document.addEventListener('input',e=>{if(e.target.closest('#payment-form')&&$('#payment-form').checkValidity())$('#finance-preview').innerHTML=indexPreview(withPayment(paymentValues()))});
document.addEventListener('submit',async e=>{if(e.target.id!=='payment-form')return;e.preventDefault();const id=$('#payment-id').value,v=paymentValues(),before=M.dashboard(state,period,0).score,b=e.target.querySelector('[type=submit]');b.disabled=true;try{if(online)await api('/api/payments/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify(v)});else{state=withPayment(v);saveLocal()}await sync();uplift=0;closeModal();render();notifyScore('Обязательство обновлено',before)}catch(err){$('#finance-error').textContent=err.message;b.disabled=false}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-finance]');if(!b)return;if(b.dataset.finance==='revenue')revenueModal();if(b.dataset.finance==='plan')planModal()});
document.addEventListener('input',e=>{const form=e.target.closest('#revenue-form,#plan-form');if(!form)return;if(form.id==='revenue-form'&&e.target.id==='revenue-date'){const h=M.adjustedHistory(state,90).find(h=>h.date===e.target.value);if(h){$('#revenue-amount').value=h.revenue-h.refunds;$('#revenue-orders').value=h.orders}}if(form.checkValidity()){$('#finance-preview').innerHTML=indexPreview(form.id==='revenue-form'?M.withRevenue(state,revenueValues()):M.withCashPlan(state,planValues()))}});
document.addEventListener('submit',async e=>{if(!['revenue-form','plan-form'].includes(e.target.id))return;e.preventDefault();const isRevenue=e.target.id==='revenue-form',v=isRevenue?revenueValues():planValues(),b=e.target.querySelector('[type=submit]'),before=M.dashboard(state,period,0).score;b.disabled=true;try{if(isRevenue&&((v.amount>0&&v.orders===0)||(v.amount===0&&v.orders!==0)))throw Error('При нулевой выручке укажите ноль покупок. Для положительной выручки — хотя бы одну покупку.');if(online)await api(isRevenue?'/api/revenue':'/api/finance-plan',{method:'PUT',body:JSON.stringify(v)});else{state=isRevenue?M.withRevenue(state,v):M.withCashPlan(state,v);saveLocal()}await sync();uplift=0;closeModal();render();notifyScore(isRevenue?'Выручка сохранена':'Финансовый план обновлён',before)}catch(err){$('#finance-error').textContent=err.message;b.disabled=false}});
